import{e as a,ab as o,a1 as s,m as r,r as n,p as i}from"./chunks/framework.BGh0NSIy.js";const g=JSON.parse('{"title":"Fight Chat Control 🔒","description":"Protect EU Digital Privacy","frontmatter":{"title":"Fight Chat Control 🔒","description":"Protect EU Digital Privacy","date":"2025-09-04T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/FCC.md","filePath":"posts/FCC.md"}'),l={name:"posts/FCC.md"};function h(c,t,p,u,d,m){const e=o("Post");return s(),r("div",null,[n(e,{authors:""}),t[0]||(t[0]=i('<h3 id="the-eu-still-wants-to-scan-your-private-messages-and-photos" tabindex="-1">The EU (still) wants to scan your private messages and photos. <a class="header-anchor" href="#the-eu-still-wants-to-scan-your-private-messages-and-photos" aria-label="Permalink to &quot;The EU (still) wants to scan your private messages and photos.&quot;">​</a></h3><p>The &quot;Chat Control&quot; proposal would mandate scanning of all private digital communications, including encrypted messages and photos. This threatens fundamental privacy rights and digital security for all EU citizens.</p><p>Every photo, every message, and every file you send will be automatically scanned—without your consent or suspicion. This is not about catching criminals; it is <em><strong>mass surveillance</strong></em> imposed on all 450 million citizens of the European Union.</p><p>EU politicians <em>exempt themselves</em> from this surveillance under &quot;professional secrecy&quot; rules. They get privacy. You and your family do not. If you&#39;re in the EU, please consider contacting Members of the European Parliament (MEPs) using the info provided on the site below:</p><h1 id="https-fightchatcontrol-eu" tabindex="-1"><a href="https://fightchatcontrol.eu/" target="_blank" rel="noreferrer">https://fightchatcontrol.eu/</a> <a class="header-anchor" href="#https-fightchatcontrol-eu" aria-label="Permalink to &quot;https://fightchatcontrol.eu/&quot;">​</a></h1><p>There is also a Change.org petition <a href="https://stopchatcontrol.eu/" target="_blank" rel="noreferrer">here</a> if you&#39;d like to sign it.</p><p>Discussion: <a href="https://redd.it/1n840p9" target="_blank" rel="noreferrer">https://redd.it/1n840p9</a></p>',7))])}const _=a(l,[["render",h]]);export{g as __pageData,_ as default};
